"""Canonical instructions and independent expectations for the guided walk."""


def step(do, expect, *, command="No explicit command; inspect the display.", prep=(), files=None, absent=(), records=None, no_action=None, special=None, epoch=None):
    return dict(do=do, expect=expect, command=command, prep=list(prep), files=files or {}, absent=list(absent),
                records=records or {}, no_action=no_action, special=special, epoch=epoch)


def case(key, title, *steps, setup=(), optional=None, cache_ttl=0.2):
    return dict(key=key, title=title, steps=list(steps), setup=list(setup), optional=optional, cache_ttl=cache_ttl)


